(function(){'use strict';
const $=id=>document.getElementById(id),phaseNames={IDLE:'待建立基准',SETTLING:'等待稳定',MEASURING:'窗口采样中',READY:'等待下一步',RUNNING:'运行 / 加热中',RETURNING:'待检测位确认',FAULT:'通信故障',FINISHED:'实验已结束'};
let lab=ITL.createLab(),auto=null,toastTimer;
const app={get lab(){return lab;},get autoDemo(){return !!auto;}};window.ITLApp=app;
function fmt(v,n=2){return typeof v==='number'&&Number.isFinite(v)?v.toFixed(n):'—';}
function escape(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4500);}
function action(fn){try{fn();render();}catch(e){toast(e.message);render();}}
function pose(){lab.setConfirmations({stopped:$('stopped').checked,positioned:$('positioned').checked,oriented:$('oriented').checked});}
function newSession(group){auto=null;lab=ITL.createLab({group:group||'ABC'});render();}
function discardConfirmed(){const s=lab.snapshot();return !s.raw.length&&!s.windows.length||window.confirm('新建实验会清除本页当前记录。请先在“实验记录”导出需要保留的数据。是否继续？');}
$('new-session').onclick=()=>{if(discardConfirmed())newSession();};
$('group').onchange=()=>action(()=>lab.setGroup($('group').value));
['stopped','positioned','oriented'].forEach(id=>$(id).onchange=()=>action(pose));
$('baseline').onclick=()=>action(()=>lab.requestBaseline());$('run').onclick=()=>action(()=>lab.startRunning());$('return').onclick=()=>action(()=>lab.returnToPoint());$('measure').onclick=()=>action(()=>lab.requestMeasurement());
$('finish').onclick=()=>action(()=>{auto=null;lab.stop();});$('recover').onclick=()=>action(()=>lab.recover());
$('comm-fault').onclick=()=>action(()=>lab.inject('communication'));$('range-fault').onclick=()=>action(()=>lab.inject('overrange'));
$('auto-demo').onclick=()=>action(()=>{if(auto){auto=null;lab.stop();return;}if(!discardConfirmed())return;newSession($('group').value);auto={stage:'baseline',cycles:0,runStart:0};lab.event('AUTO_DEMO','全部机床确认均为虚拟确认，不控制CNC');lab.setConfirmations({stopped:true,positioned:true,oriented:true});lab.requestBaseline();});
function advanceDemo(){if(!auto)return;const s=lab.snapshot();if(s.phase==='FAULT'||s.phase==='FINISHED'){auto=null;return;}
 if(s.windows.length&&!s.windows[s.windows.length-1].valid){auto=null;lab.event('AUTO_DEMO_PAUSED','窗口无效；保留基准与数据，等待手动修正');toast('窗口无效，自动演示已停止。记录保留，请重新确认检测位后采样。');return;}
 if(auto.stage==='baseline'&&s.baselineReady){lab.startRunning();auto.stage='run';auto.runStart=lab.now();}
 else if(auto.stage==='run'&&lab.now()-auto.runStart>=12){lab.returnToPoint();lab.event('AUTO_POSE_CONFIRMATION','模拟停转、同向到位及角向复位');lab.setConfirmations({stopped:true,positioned:true,oriented:true});lab.requestMeasurement();auto.stage='window';}
 else if(auto.stage==='window'&&s.phase==='READY'){auto.cycles++;if(auto.cycles>=3){lab.event('AUTO_DEMO_COMPLETE','3个有效热窗口；可以导出或手动继续');auto=null;}else{lab.startRunning();auto.runStart=lab.now();auto.stage='run';}}
}
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{document.querySelectorAll('.view').forEach(v=>v.classList.toggle('hidden',v.id!==button.dataset.view));document.querySelectorAll('.nav').forEach(v=>v.classList.toggle('active',v===button));render();});
document.querySelectorAll('[data-export]').forEach(button=>button.onclick=()=>{const key=button.dataset.export,files=lab.exportData(),isJson=key==='metadataJson',data=(isJson?'':'\ufeff')+files[key];const url=URL.createObjectURL(new Blob([data],{type:isJson?'application/json;charset=utf-8':'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=lab.snapshot().experimentId+'_'+key+(isJson?'.json':'.csv');a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('已导出 '+a.download);});
function chart(canvas,series){const width=Math.max(260,canvas.clientWidth),height=210,ratio=window.devicePixelRatio||1;canvas.width=width*ratio;canvas.height=height*ratio;const c=canvas.getContext('2d');c.scale(ratio,ratio);c.clearRect(0,0,width,height);const p={l:42,r:14,t:12,b:28},w=width-p.l-p.r,h=height-p.t-p.b;const all=series.flatMap(s=>s.points).filter(p=>Number.isFinite(p[0])&&Number.isFinite(p[1]));let minX=0,maxX=Math.max(10,...all.map(p=>p[0])),minY=Math.min(0,...all.map(p=>p[1])),maxY=Math.max(1,...all.map(p=>p[1]));if(series[0]&&series[0].temperature){minY=all.length?Math.floor(Math.min(...all.map(p=>p[1]))-1):19;maxY=all.length?Math.ceil(Math.max(...all.map(p=>p[1]))+1):25;}if(maxY-minY<1)maxY=minY+1;const sx=x=>p.l+(x-minX)/(maxX-minX)*w,sy=y=>p.t+h-(y-minY)/(maxY-minY)*h;c.font='10px system-ui';c.lineWidth=1;for(let i=0;i<=4;i++){const yy=p.t+i*h/4;c.strokeStyle='#edf1f3';c.beginPath();c.moveTo(p.l,yy);c.lineTo(width-p.r,yy);c.stroke();c.fillStyle='#98a6ae';c.textAlign='right';c.fillText((maxY-i*(maxY-minY)/4).toFixed(1),p.l-7,yy+3);}for(let i=0;i<=4;i++){c.textAlign='center';c.fillText((maxX*i/4).toFixed(0),sx(maxX*i/4),height-7);}series.forEach(s=>{c.strokeStyle=s.color;c.fillStyle=s.color;c.lineWidth=2;c.beginPath();let drawing=false;s.points.forEach(v=>{if(!Number.isFinite(v[1])){drawing=false;return;}const x=sx(v[0]),y=sy(v[1]);if(drawing)c.lineTo(x,y);else c.moveTo(x,y);drawing=true;});c.stroke();if(s.markers)s.points.forEach(v=>{if(!Number.isFinite(v[1]))return;c.beginPath();c.arc(sx(v[0]),sy(v[1]),3,0,Math.PI*2);c.fill();});});if(!all.length){c.fillStyle='#a2aeb5';c.textAlign='center';c.fillText('完成有效测量窗口后显示',width/2,height/2);}}
function render(){const s=lab.snapshot(),r=s.latest,valid=s.windows.filter(w=>w.kind==='thermal'&&w.valid);$('session-id').textContent=s.experimentId;$('wall-time').textContent=String(Math.floor(s.elapsedWallSec/60)).padStart(2,'0')+':'+String(Math.floor(s.elapsedWallSec%60)).padStart(2,'0');$('sim-time').textContent=(s.simulationTimeSec/60).toFixed(1)+' min';$('phase').textContent=phaseNames[s.phase];$('phase').classList.toggle('fault',s.phase==='FAULT');$('group').value=s.group;$('group').disabled=s.phase!=='IDLE'||s.baselineReady;
 ['stopped','positioned','oriented'].forEach(id=>{$(id).checked=s.confirmations[id];$(id).disabled=['RUNNING','FAULT','FINISHED'].includes(s.phase)||!!auto;});
 const confirmed=Object.values(s.confirmations).every(Boolean);$('baseline').disabled=!!auto||s.baselineReady||s.phase!=='IDLE'||!confirmed;$('run').disabled=!!auto||!s.baselineReady||s.phase!=='READY';$('return').disabled=!!auto||!['RUNNING','READY'].includes(s.phase)||!s.baselineReady;$('measure').disabled=!!auto||s.phase!=='RETURNING'||!confirmed;$('recover').disabled=s.phase!=='FAULT';$('finish').disabled=s.phase==='FINISHED';$('comm-fault').disabled=s.phase==='FINISHED';$('range-fault').disabled=s.phase==='FINISHED';$('new-session').disabled=!!auto;$('auto-demo').textContent=auto?'停止演示':'自动演示';
 $('step-baseline').className=s.baselineReady?'done':'current';$('step-run').className=s.phase==='RUNNING'?'current':'';$('step-window').className=['RETURNING','SETTLING','MEASURING'].includes(s.phase)&&s.baselineReady?'current':'';
 $('window-status').textContent=s.windowKind?(s.phase==='SETTLING'?'稳定等待剩余 '+fmt(s.settleRemaining,1)+' s':'正在采样')+' · '+s.windowCount+' / '+s.windowTarget+' 点':s.phase==='RUNNING'?'运行时主轴旋转；正式测量前需停转并复位。':s.phase==='RETURNING'?'返回固定检测点，以相同方向到位，再完成三项确认。':'每轮只建立一次基准；演示窗口为 2 s 等待 + 5 点。';
 ['x','y','z'].forEach((id,i)=>$(id).textContent=s.lastXYZ?fmt(s.lastXYZ[i]):'—');$('valid-count').textContent=valid.length+' 个热窗口';$('baseline-status').textContent='冷态基准：'+(s.baselineReady?'已建立 / 本轮冻结':'未建立');$('rms').textContent='有效窗口向量 RMS：'+fmt(s.rmsUm)+' μm';
 $('cooling-rows').innerHTML=['A1','A2','B1','B2','C1','C2'].map((name,i)=>'<tr><td><strong>'+name+'</strong></td><td>'+['床身','床身','立柱','立柱','横梁','横梁'][i]+'</td><td>'+fmt(s.command[i],0)+'</td><td>'+fmt(r?r.opening[i]:NaN,1)+'</td><td>'+fmt(r?r.flow[i]:NaN)+'</td><td>'+fmt(r?r.waterIn[i]:NaN,1)+' / '+fmt(r?r.waterOut[i]:NaN,1)+'</td></tr>').join('');
 $('queue-status').textContent='已完成 '+s.bus.completed+' 请求 · 最大并发 '+s.bus.maxConcurrent;$('events').innerHTML=s.events.slice(-8).reverse().map(e=>'<div class="event"><time>'+fmt(e.elapsedWallSec,1)+' s</time><span>'+escape(e.action)+'<br>'+escape(e.detail)+'</span></div>').join('');
 $('temperature-grid').innerHTML=s.temperatureNames.map((name,i)=>'<div class="temp"><small>T'+(i+1)+' · '+escape(name)+'</small><strong>'+fmt(r?r.temps[i]:NaN,2)+'</strong> <span class="small muted">°C</span></div>').join('');
 $('window-rows').innerHTML=s.windows.map(w=>'<tr><td>'+(w.kind==='baseline'?'冷态基准':'热位移')+'</td><td>'+escape(w.endTimeIso)+'</td><td>'+w.count+'</td><td>'+(w.valid?'有效':'无效')+'</td><td>'+w.xyz.map(v=>fmt(v)).join(' / ')+'</td><td>'+escape(w.reason)+'</td></tr>').join('');$('record-count').textContent=s.windows.length+' 个窗口';$('raw-rows').innerHTML=s.raw.slice(-50).reverse().map(r=>'<tr><td>'+fmt(r.elapsedWallSec,1)+'</td><td>'+fmt(r.simulationTimeSec,0)+'</td><td>'+escape(r.phase)+'</td><td>'+r.probes.map(v=>fmt(v)).join(' / ')+'</td><td>'+escape(r.quality)+'</td></tr>').join('');
 const colors=['#276cf1','#169b91','#de922c','#9c6cc0'];chart($('xyz-chart'),[0,1,2].map(i=>({color:colors[i],markers:true,points:s.windows.filter(w=>w.valid).map(w=>[w.endWallSec,w.xyz[i]])})));chart($('temperature-chart'),[0,1,3,17].map((i,k)=>({temperature:true,color:colors[k],points:s.raw.map(r=>[r.elapsedWallSec,r.temps[i]])})));
}
setInterval(()=>{try{lab.tick();advanceDemo();render();}catch(e){auto=null;toast(e.message);}},1000);window.addEventListener('resize',render);render();
})();
